INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rasvyat Nuclear Power Station', 'Rasvyat Nuclear Power Station is a physics-based nuclear reactor simulation where players operate and maintain a functioning power plant. Using realistic calculations, players must keep the reactor stable while responding to various emergencies including system failures and power outages. Every operator decision has long-term consequences, with mistakes potentially leading to reactor trips, equipment damage, or catastrophic meltdowns.' FROM games WHERE igdb_id = 292465 ON CONFLICT (game_id, language_code) DO NOTHING;
