INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Isekaing: From Zero to Zero', 'Zoe is hit by the Truck-kun, and respawns in a pixel-art game, where she must face dangers in form of clichés, meaningless choices, a plot that has more holes than Swiss cheese, and other plagues of modern gaming. Also, every notable person is trying to sing her a song! Will she endure such torment?' FROM games WHERE igdb_id = 323548 ON CONFLICT (game_id, language_code) DO NOTHING;
