INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Correct Picture', 'Correct Picture is an engaging and educational game where players are challenged to match pictures on the left with their corresponding names on the right. The objective is to correctly pair as many names with images as possible. The more correct matches a player makes, the higher their score. This game tests and improves the player''s recognition and association skills, making it both fun and informative.' FROM games WHERE igdb_id = 314685 ON CONFLICT (game_id, language_code) DO NOTHING;
