INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Foot Step', 'Foot Step is a game in which you need to control a little man and dodge kicks. When it comes into contact with cells, the foot will destroy them underneath it, but if the foot collides with a round object, the foot will not be able to break through it and will stop on this line, turning the round object into a regular cell. The goal of the game is to advance gradually without getting kicked or falling onto the spikes below.' FROM games WHERE igdb_id = 320951 ON CONFLICT (game_id, language_code) DO NOTHING;
