INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gui Long Chao', 'Gui Long Chao is a 3D action-adventure game It takes place in a new city "Kowloon", where tradition and modernity collide. As its name suggests, the city consists of nine neighborhoods, where the streets and alleys are filled with a retro, trendy and bizarre atmosphere. Of course, in the corners where the streetlights don''t shine, there are also treacherous undercurrents. You will play the role of a "film director", form a "crew", and set out to collect clues under the guise of "filming" in the nine neighborhoods, where order and chaos coexist in different styles, to gradually uncover the truth buried in the city.' FROM games WHERE igdb_id = 317049 ON CONFLICT (game_id, language_code) DO NOTHING;
