INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Torture House', 'In September 1994, Victoria Atkins, a young aspiring model, was traveling through Cooke County, Texas, in search of job opportunities when she suddenly disappeared. While it was initially believed she had simply become lost on the road, days passed without any sign of her. But what no one could imagine were the horrors of the ultra violence she would experience in a place that could easily be described as hell, The Torture House.' FROM games WHERE igdb_id = 303177 ON CONFLICT (game_id, language_code) DO NOTHING;
