INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mombo Combo Legacy', 'Mombo Combo Legacy is a fast-paced platformer packed with action and adventure! Battle monstrous enemies, unlock powerful forms, and pull off incredible combos across hundreds of handcrafted levels. Customize your Mombo with stylish skins, collect and evolve Orumon pets, and take down epic bosses in your quest to save the universe. Easy to play, hard to master — and all powered by skill, courage… and a whole lot of tongue.' FROM games WHERE igdb_id = 326858 ON CONFLICT (game_id, language_code) DO NOTHING;
