INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DanceDanceRevolution World', 'DanceDanceRevolution World is the 19th installment of the Dance Dance Revolution arcade series in Japan (and the 10th outside of Japan). The game was released as a software upgrade for LCD-based arcade cabinets on June 12, 2024, in Asia, Australasia, and the United States. It is the sequel to Dance Dance Revolution A3, and is currently the most recent release.' FROM games WHERE igdb_id = 305995 ON CONFLICT (game_id, language_code) DO NOTHING;
