INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oreo Pac-Man', 'Oreo Pac-Man is a promotional web browser game made in collaboration between Oreo and Bandai Namco. The game was made to promote Pac-Man themed Oreo cooked and the Oreo Pac-Man contest, in which the participants have a chance to win a trip to Japan or an Arcade1UP arcade machine, with European regions also having the additional prize of a mini LCD arcade game for the promotion. Current it has only been released within Europe, Australia and New Zealand.' FROM games WHERE igdb_id = 314771 ON CONFLICT (game_id, language_code) DO NOTHING;
