INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pet Crossing', 'A cruiser came to a blue planet and found a planet with many ice-blocked caves, which contained frozen animals that were sent in before the catastrophe. Only paired animals could survive after thawing. The expedition team needs your wisdom to help match these animals and restore life to the planet.' FROM games WHERE igdb_id = 310034 ON CONFLICT (game_id, language_code) DO NOTHING;
