INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chasing Bottaflies', 'Chasing Bottaflies is a short puzzle-adventure game, featuring the character Fluffle Puff who got lost in a deep forest. To find her way home she will have to capture various "bottaflies", most of which are hidden in secret places that need good observation skills or understanding of various hints to be found. Going through three surprising areas, she will eventually find a bottafly big enough to carry her back... and maybe something else.' FROM games WHERE igdb_id = 286567 ON CONFLICT (game_id, language_code) DO NOTHING;
