INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fruit Merge', 'Fruit Merge is a puzzle game where players merge matching fruits to create bigger ones, ultimately aiming to make watermelons. You drop and position fruits strategically to set up merges, managing space to prevent the container from overflowing. The game challenges you to plan your moves carefully as larger fruits take up more room, and it rewards progression with higher-level fruits. The goal is to keep merging while avoiding game over and reaching the highest fruit size possible.' FROM games WHERE igdb_id = 322806 ON CONFLICT (game_id, language_code) DO NOTHING;
