INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cooking Arena Doner Delight', 'Your adventure begins with Food Truck Tycoon, where you can cook, chop, bake, and enjoy hundreds of unique dishes. But the journey of a thousand dishes is just the beginning! As you hone your cooking skills and build your reputation with food trucks, you''ll be given the opportunity to explore more gourmet games as DLC. Customize your kitchen with countless upgrades and serve delicious food in different locations, keeping the grill hot, your customers smiling, and sautéing, mixing, and serving to the top. Face cooking challenges to become the ultimate chef in town! So put on your apron, sharpen your knives, and enter the cooking arena - life is a party, so let''s cook delicious!' FROM games WHERE igdb_id = 317896 ON CONFLICT (game_id, language_code) DO NOTHING;
